package bd.hscsolution.student.theme; import android.content.*; import androidx.appcompat.app.AppCompatDelegate; public final class ThemeManager{private ThemeManager(){} public static void apply(Context c){String x=c.getSharedPreferences("ui",0).getString("theme","system");AppCompatDelegate.setDefaultNightMode("dark".equals(x)?AppCompatDelegate.MODE_NIGHT_YES:"light".equals(x)?AppCompatDelegate.MODE_NIGHT_NO:AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM);}public static void set(Context c,String x){c.getSharedPreferences("ui",0).edit().putString("theme",x).apply();apply(c);}}